static unsigned early_frame_busy,destroy_frame_busy;
SatchelGuestTextureFrameStatus window_test_frame_poll(SatchelGuestTextureFrames*f,uint32_t ms,int cancel,SatchelGuestTextureFrameReport*out){if(early_frame_busy){early_frame_busy--;return SATCHEL_GTF_BUSY;}return satchel_guest_texture_frames_poll(f,ms,cancel,out);}
SatchelGuestTextureFrameStatus window_test_frame_destroy(SatchelGuestTextureFrames**f){if(destroy_frame_busy){destroy_frame_busy--;return SATCHEL_GTF_BUSY;}return satchel_guest_texture_frames_try_destroy(f);}

uint32_t window_test_present_poll(SatchelGuestTransfers*q,uint64_t lease,uint32_t ms,int cancel,SatchelGuestPresentQueueProgress*out){uint32_t result=satchel_guest_transfers_present_poll(q,lease,ms,cancel,out);if(cancel_after_poll){cancel_after_poll->cancel=1;cancel_after_poll=NULL;}if(revoke_after_poll){revoke_after_poll->alive=0;revoke_after_poll=NULL;}return result;}
uint32_t window_test_texture_retain(SatchelGuestTextures*t,SatchelCPUProbe*c,uint64_t object,uint64_t*ref,SatchelGuestTextureBinding*b){uint32_t result=satchel_guest_textures_retain(t,c,object,ref,b);if(cancel_after_retain){cancel_after_retain->cancel=1;cancel_after_retain=NULL;}return result;}

SatchelCPUWriteResult window_test_writev(SatchelCPUProbe*c,const SatchelCPUProbeWrite*w,size_t n){if(write_reentry){SatchelGuestWindowStats s;CHECK(satchel_guest_windows_stats(write_reentry,&s)==SATCHEL_GWIN_BUSY);}if(window_write_failure){window_write_failure--;return SATCHEL_CPU_WRITE_ALLOCATION;}return satchel_cpu_probe_writev(c,w,n);}
static int wdevice(void*p,SatchelCPUProbe*c,uint64_t a,uint64_t*t,uint64_t*g){return dv(&((World*)p)->gpu,c,a,t,g);}
static int wguard(void*p,SatchelCPUProbe*c,uint64_t a,uint64_t n){World*w=p;Fixture*f=&w->gpu;return !w->deny&&pg(f,c,a,n)&&!satchel_guest_transfers_guard(f->transfers,c,a,n)&&!satchel_guest_pools_check_unowned_range_checked(f->pools,c,a,n);}
static int vguard(void*p,SatchelCPUProbe*c,uint64_t a,size_t n){World*w=p;return wguard(p,c,a,n)&&(!w->window||satchel_guest_windows_guard(w->window,c,a,n));}
static int reservation(void*p,SatchelCPUProbe*c,const SatchelGuestVIReservation*r){World*w=p;return c==w->gpu.cpu&&!memcmp(r,&w->config.reservation,sizeof(*r))&&satchel_cpu_probe_set_permissions(c,WID,4096,0,0)==SATCHEL_CPU_MAP_OK;}
static int claim_reservation(void*p,SatchelCPUProbe*c,const SatchelGuestVIReservation*r){World*w=p;if(w->claimed||!reservation(p,c,r))return 0;w->claimed=1;return 1;}
static int context(void*p,SatchelCPUProbe*c,uint64_t process,uint64_t generation){World*w=p;w->contexts++;return w->alive&&c==w->gpu.cpu&&process==w->config.reservation.process_id&&generation==1000+process;}
static int wcancel(void*p){return ((World*)p)->cancel;}
static int surface_policy(void*p,const SatchelGuestVIInfo*i,int32_t interval,uint32_t width,uint32_t height,SatchelGuestWindowPresentation*out){World*w=p;if(!w->policy||interval!=7||width!=31||height!=17||i->surface_epoch!=77)return 0;/* Explicit ORIGINAL test policy, not NVN interval semantics. */*out=(SatchelGuestWindowPresentation){1,sizeof(*out),SATCHEL_FRAME_RGBA8_UNORM,SATCHEL_FRAME_LINEAR_SRGB,SATCHEL_FRAME_TOP_LEFT,77,1};return 1;}
static uint64_t readword(SatchelCPUProbe*c,uint64_t a){uint8_t b[8];CHECK(satchel_cpu_probe_read(c,a,b,8));uint64_t v=0;for(unsigned i=0;i<8;i++)v|=(uint64_t)b[i]<<(i*8);return v;}
static SatchelGuestVIStatus vi_call(World*w,unsigned op,uint64_t a,uint64_t b){CHECK(satchel_cpu_probe_set_pc(w->gpu.cpu,0x100000));SatchelGuestVIResult r;return satchel_guest_vi_execute(w->vi,&w->borrow.vi,op,a,b,0x100000,0x100004,&r);}
static SatchelGuestWindowStatus wc(World*w,unsigned op,uint64_t a,uint64_t b,uint64_t c,uint64_t d,uint64_t e,SatchelGuestWindowResult*out){SatchelGuestWindowRequest q={op,{a,b,c,d,e,0}};return satchel_guest_windows_execute(w->window,&w->borrow,&q,out);}
