static void init(World*w){CHECK(W(w,SATCHEL_GWIN_INITIALIZE,WIN,WB,0,0,0,0)==1);W(w,SATCHEL_GWIN_SET_INTERVAL,WIN,7,0,0,0,0);W(w,SATCHEL_GWIN_SET_CROP,WIN,0,0,31,17,0);}
